import type { Metadata } from 'next';

export const SITE_URL = 'https://myglo.app';
export const SITE_NAME = 'MyGlo';
export const SITE_LOCALE = 'en_AU';
export const SITE_DESCRIPTION =
    'MyGlo is the all-in-one beauty booking app coming soon to Australia. Discover local hair, makeup and nail artists through their work, and book in one place.';
export const CONTACT_EMAIL = 'hello@myglo.app';
export const INSTAGRAM_URL = 'https://www.instagram.com/myglo.app/';

// Generated by app/opengraph-image.tsx and app/twitter-image.tsx
export const SHARE_IMAGE = {
    width: 1200,
    height: 630,
    alt: 'MyGlo - The all-in-one beauty booking platform, coming soon to Australia',
};

// Operator details, as published in the Terms of Service and Privacy Policy
export const LEGAL_ENTITY = {
    name: 'Nexotec Pty Ltd',
    abn: '12 674 499 024',
    region: 'QLD',
    country: 'AU',
};

type PageMetadataInput = {
    // Shown as "<title> | MyGlo" via the root layout's title template
    title: string;
    description: string;
    // Path relative to SITE_URL, e.g. '/terms'
    path: string;
    // Use the title as-is instead of applying the template (homepage)
    absoluteTitle?: boolean;
};

// Builds per-page metadata with a self-referencing canonical URL and matching
// Open Graph / Twitter tags. Child `openGraph` objects replace the parent's
// entirely in Next.js (including file-based share images), so the shared fields
// and images are repeated here.
export function pageMetadata({ title, description, path, absoluteTitle = false }: PageMetadataInput): Metadata {
    const fullTitle = absoluteTitle ? title : `${title} | ${SITE_NAME}`;

    return {
        title: absoluteTitle ? { absolute: title } : title,
        description,
        alternates: {
            canonical: path,
        },
        openGraph: {
            type: 'website',
            siteName: SITE_NAME,
            locale: SITE_LOCALE,
            url: path,
            title: fullTitle,
            description,
            images: [{ url: '/opengraph-image', type: 'image/png', ...SHARE_IMAGE }],
        },
        twitter: {
            card: 'summary_large_image',
            title: fullTitle,
            description,
            images: [{ url: '/twitter-image', type: 'image/png', ...SHARE_IMAGE }],
        },
    };
}
